WITH with_windows AS (SELECT *, LAG(balance, 1, 0) OVER (PARTITION BY account_type ORDER BY opened_date, id) AS prev_balance, NTILE(3) OVER (PARTITION BY customer_id, account_type ORDER BY balance, id) AS balance_bucket, AVG(balance) OVER (PARTITION BY customer_id ORDER BY opened_date, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS balance_avg_6, AVG(balance) OVER (PARTITION BY status ORDER BY balance, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS balance_avg_6_2 FROM accounts) SELECT id, customer_id, account_type, balance, opened_date, prev_balance, balance_avg_6, balance_avg_6_2 FROM with_windows ORDER BY account_type DESC
